// This variable will be set dynamically from your app
let currentSelectedCell = null;

export const setSelectedCellContext = (cell) => {
  currentSelectedCell = cell;
};

const button = {
    root: ({ props, context }) => ({
        className: classNames(
            // Base class - following uls-[component_name] rule
            'uls-button',
            
            // Severity variations - following uls-button [variation] rule
            {
                'primary': props.severity === 'primary' || !props.severity,
                'secondary': props.severity === 'secondary',
                'success': props.severity === 'success',
                'info': props.severity === 'info',
                'warning': props.severity === 'warning',
                'help': props.severity === 'help',
                'danger': props.severity === 'danger',
            },
            
            // Visual variants - following variation pattern
            {
                'outlined': props.outlined,
                'text': props.text,
                'raised': props.raised,
                'rounded': props.rounded,
                'link': props.link,
                'icon-only': !props.label && props.icon
            },
            
            // Size variations
            {
                'xs-size': props.size === 'xs' || props.size === 'extra-small',
                's-size': props.size === 'small' || props.size === 's' || !props.size, // Default size
                'm-size': props.size === 'medium' || props.size === 'm',
                'l-size': props.size === 'large' || props.size === 'l',
                'xl-size': props.size === 'xl' || props.size === 'extra-large'
            },
            
            // States
            {
                'disabled': props.disabled || context.disabled,
                'loading': props.loading
            }
        )
    }),
    
    label: ({ props }) => ({
        className: classNames(
            'uls-button-label',
            {
                'loading': props.loading
            }
        )
    }),
    
    icon: ({ props }) => ({
        className: classNames(
            'uls-button-icon',
            {
                'left': props.iconPos === 'left',
                'right': props.iconPos === 'right',
                'icon-only': !props.label && props.icon
            }
        )
    }),
    
    badge: ({ props }) => ({
        className: classNames(
            'uls-button-badge',
            props.badgeClassName
        )
    }),
    
    loadingIcon: ({ props }) => ({
        className: classNames(
            'uls-button-loading-icon',
            {
                'left': props.iconPos !== 'right',
                'right': props.iconPos === 'right'
            }
        )
    })
};

