const inputtext = {
    root: ({ props, context }) => ({
        className: classNames(
            // Base class - following uls-[component_name] rule
            'uls-inputtext',
            'uls-input', // Base input class for shared styles
            
            // Size variations - following ULS convention
            {
                'xs-size': props.size === 'xs' || props.size === 'extra-small',
                's-size': props.size === 'small' || props.size === 's',
                'm-size': props.size === 'medium' || props.size === 'm' || !props.size,
                'l-size': props.size === 'large' || props.size === 'l',
                'xl-size': props.size === 'xl' || props.size === 'extra-large'
            },
            
            // Visual variants
            (() => {
                const parentVariant = props.__parentMetadata?.parent?.props?.variant;
                const v = props.variant ?? parentVariant;
                return {
                    'outlined': !v || v === 'outlined',
                    'filled': v === 'filled'
                };
            })(),
            
            // States
            {
                'disabled': props.disabled || context.disabled,
                'invalid': props.invalid,
                'readonly': props.readOnly
            }
        )
    })
};

