// ✅ ULS TabPanel Passthrough (Fixed + Closable + Scrollable)
const tabpanel = {
    header: ({ props, context, options, ptOptions }) => {
        const tabIndex = options?.index ?? context?.index;
        const activeIndex = ptOptions?.activeIndex ?? context?.activeIndex ?? context?.parent?.activeIndex;
        const isActive = tabIndex === activeIndex;

        return {
            className: classNames('tabview-header', {
                'active': context?.active,
                'uls-highlight': context?.active,
                'disabled': props.disabled
            }),
            'data-pc-section': 'header' // 👈 Retain section attribute
        };
    },

    headerAction: ({ props, context }) => ({
        className: 'tabview-header-action',
        'data-pc-section': 'headeraction' // 👈 Required for tab switching logic
    }),

    headerTitle: ({ props, context }) => ({
        className: 'tabview-header-title',
        'data-pc-section': 'headertitle'
    }),

    headerIcon: ({ props, context }) => ({
        className: 'tabview-header-icon',
        'data-pc-section': 'headericon'
    }),

    closeIcon: ({ props, context }) => ({
        className: 'tabview-close-icon',
        'data-pc-section': 'closeicon' // 👈 REQUIRED for closing individual tabs
    }),

    content: ({ props, context, ptOptions }) => {
        const isActive = context?.active ?? props.index === ptOptions?.activeIndex;

        return {
            className: classNames('tabview-panel', { 'active': isActive }),
            'data-pc-section': 'content' // 👈 Important for transitions and state
        };
    }
};

