// TieredMenu Passthrough
const tieredmenu = {
    root: ({ props, state }) => ({
        className: classNames(
            'uls-tieredmenu',
            {
                // Popup/overlay mode
                'popup': props.popup,
                'overlay': props.popup,
                // Visibility (if provided by component state)
                'open': state?.overlayVisible
            },
            // Animation states
            {
                'enter': state?.enter,
                'enter-active': state?.enterActive,
                'enter-done': state?.enterDone,
                'exit': state?.exit,
                'exit-active': state?.exitActive,
                'exit-done': state?.exitDone
            },
            props.className
        )
    }),

    // UL list container
    menu: () => ({
        className: classNames('tieredmenu-list')
    }),

    // LI element for each item
    menuitem: ({ context }) => ({
        className: classNames(
            'tieredmenu-item',
            {
                'active': context?.active,
                'highlight': context?.highlight,
                'disabled': context?.disabled,
                'separator': context?.separator,
                'has-submenu': context?.hasSubmenu
            }
        )
    }),

    // Anchor/button inside item
    content: ({ context }) => ({
        className: classNames(
            'tieredmenu-item-link',
            {
                'disabled': context?.disabled
            }
        )
    }),

    // Icon span
    icon: ({ context }) => ({
        className: classNames(
            'tieredmenu-item-icon',
            {
                'disabled': context?.disabled
            }
        )
    }),

    // Label span
    label: ({ context }) => ({
        className: classNames(
            'tieredmenu-item-label',
            {
                'disabled': context?.disabled
            }
        )
    }),

    // Horizontal rule/separator item
    separator: () => ({
        className: classNames('tieredmenu-separator')
    }),

    // Submenu container (for nested menus)
    submenu: ({ context, state, options }) => {
        // Check multiple possible properties for submenu visibility
        // PrimeReact may use expanded, visible, submenuVisible, or parent menuitem's active state
        const parentContext = options?.context || options?.parentContext || context?.parent;
        const isOpen = context?.expanded || 
                      context?.visible || 
                      context?.submenuVisible || 
                      state?.visible ||
                      state?.expanded ||
                      parentContext?.expanded ||
                      parentContext?.visible ||
                      parentContext?.active ||
                      parentContext?.highlight;
        
        return {
            className: classNames(
                'tieredmenu-submenu',
                {
                    'open': !!isOpen,
                    'closed': !isOpen
                }
            )
        };
    },

    // Submenu header (if applicable)
    submenuHeader: () => ({
        className: classNames('tieredmenu-submenu-header')
    }),

    // Action wrapper
    action: () => ({
        className: classNames('tieredmenu-action')
    })
};

