// Stepper Passthrough
const stepper = {
    root: ({ props }) => ({
        className: classNames(
            // Base class - following uls-[component_name] rule
            'uls-stepper',
            
            // Orientation variants
            {
                'horizontal': props.orientation !== 'vertical',
                'vertical': props.orientation === 'vertical'
            },
            
            // Header position variants
            {
                'header-top': props.headerPosition === 'top',
                'header-right': props.headerPosition === 'right' || !props.headerPosition, // Default
                'header-left': props.headerPosition === 'left',
                'header-bottom': props.headerPosition === 'bottom'
            },
            
            // Behavior variants
            {
                'linear': props.linear,
                'non-linear': !props.linear
            },
            
            props.className
        )
    }),
    
    nav: ({ props }) => ({
        className: classNames(
            'stepper-nav',
            {
                'horizontal': props.orientation !== 'vertical',
                'vertical': props.orientation === 'vertical'
            }
        )
    }),
    
    list: () => ({
        className: classNames('stepper-list')
    }),
    
    step: ({ context, options }) => {
        const stepContext = options?.context ?? context ?? {};
        const parentMeta = stepContext?.parent ?? {};
        const activeIndex = parentMeta?.state?.activeIndex ?? parentMeta?.props?.activeIndex ?? 0;
        const index = stepContext?.index ?? stepContext?.itemIndex ?? 0;
        const isActive = index === activeIndex;
        const isCompleted = index < activeIndex;
        
        return {
            className: classNames('stepper-step', {
                'active': isActive,
                'completed': isCompleted,
                'disabled': stepContext?.disabled,
                'first': stepContext?.first ?? index === 0,
                'last': stepContext?.last
            })
        };
    },
    
    header: ({ context, options }) => {
        const stepContext = options?.context ?? context ?? {};
        const parentMeta = stepContext?.parent ?? {};
        const activeIndex = parentMeta?.state?.activeIndex ?? parentMeta?.props?.activeIndex ?? 0;
        const index = stepContext?.index ?? stepContext?.itemIndex ?? 0;
        const isActive = index === activeIndex;
        const isCompleted = index < activeIndex;
        
        return {
            className: classNames('stepper-header', {
                'active': isActive,
                'completed': isCompleted,
                'disabled': stepContext?.disabled,
                'highlight': isActive || isCompleted
            })
        };
    },
    
    panels: () => ({
        className: classNames('stepper-panels')
    }),
    
    panelcontainer: () => ({
        className: classNames('stepper-panel-container')
    }),
    
    panel: ({ context, options }) => {
        const panelContext = options?.context ?? context ?? {};
        const parentMeta = panelContext?.parent ?? {};
        const activeIndex = parentMeta?.state?.activeIndex ?? parentMeta?.props?.activeIndex ?? 0;
        const index = panelContext?.index ?? panelContext?.itemIndex ?? 0;
        const isActive = index === activeIndex;
        
        return {
            className: classNames('stepper-panel', {
                'active': isActive,
                'disabled': panelContext?.disabled
            })
        };
    },
    
    content: ({ context, options }) => {
        const panelContext = options?.context ?? context ?? {};
        const parentMeta = panelContext?.parent ?? {};
        const activeIndex = parentMeta?.state?.activeIndex ?? parentMeta?.props?.activeIndex ?? 0;
        const index = panelContext?.index ?? panelContext?.itemIndex ?? 0;
        const isActive = index === activeIndex;
        
        return {
            className: classNames('stepper-content', {
                'active': isActive,
                'disabled': panelContext?.disabled
            })
        };
    }
};

