// ContextMenu Passthrough
const contextmenu = {
    root: ({ props, state }) => ({
        className: classNames(
            'uls-contextmenu',
            {
                // Popup/overlay mode (always true for ContextMenu)
                'popup': true,
                'overlay': true,
                // Global mode (attached to document)
                'global': props.global,
                // Visibility (if provided by component state)
                'open': state?.overlayVisible
            },
            // Animation states
            {
                'enter': state?.enter,
                'enter-active': state?.enterActive,
                'enter-done': state?.enterDone,
                'exit': state?.exit,
                'exit-active': state?.exitActive,
                'exit-done': state?.exitDone
            },
            props.className
        )
    }),

    // UL list container (root list)
    menu: ({ state, props, context, options }) => {
        
        return { className: classNames('contextmenu-root-list') };
    },

    // LI element for each item
    menuitem: ({ context, options, state, props }) => {
        console.log("context", context);
        console.log("options", options);
        console.log("state", state);
        console.log("props", props);
        return {
            className: classNames(
                'contextmenu-item',
                {
                    'active': context?.active,
                    'highlight': context?.highlight,
                    'disabled': context?.disabled,
                    'separator': context?.separator,
                    'has-submenu': context?.hasSubmenu
                }
            )
        };
    },

    // Anchor/button inside item
    content: ({ context }) => ({
        className: classNames(
            'contextmenu-item-link',
            {
                'active': context?.active,
                'disabled': context?.disabled
            }
        )
    }),

    // Icon span
    icon: ({ context }) => ({
        className: classNames(
            'contextmenu-item-icon',
            {
                'disabled': context?.disabled
            }
        )
    }),

    // Label span
    label: ({ context }) => ({
        className: classNames(
            'contextmenu-item-label',
            {
                'disabled': context?.disabled
            }
        )
    }),

    // Badge element (for menu items with badge property)
    // Note: PrimeReact ContextMenu may not natively support badges via passthrough
    // If this section is not called, badges need to be rendered via template property
    badge: ({ context, props }) => {
        return {
            className: classNames(
                'contextmenu-item-badge',
                {
                    'disabled': context?.disabled
                },
                props?.badgeClassName
            )
        };
    },

    // Shortcut element (for menu items with shortcut property)
    shortcut: ({ context }) => ({
        className: classNames(
            'contextmenu-item-shortcut',
            {
                'disabled': context?.disabled
            }
        )
    }),

    // Horizontal rule/separator item
    separator: () => ({
        className: classNames('contextmenu-separator')
    }),

    // Group header within the menu
    submenuHeader: () => ({
        className: classNames('contextmenu-submenu-header')
    }),

    // Submenu container (for nested menus)
    submenu: ({ context, state, options }) => {
        const parentContext = options?.context || options?.parentContext || context?.parent;
        const isOpen = context?.expanded || 
                      context?.visible || 
                      context?.submenuVisible || 
                      state?.visible ||
                      state?.expanded ||
                      parentContext?.expanded ||
                      parentContext?.visible ||
                      parentContext?.active ||
                      parentContext?.highlight;
        
        return {
            className: classNames(
                'contextmenu-submenu',
                {
                    'open': !!isOpen,
                    'closed': !isOpen
                }
            )
        };
    },

    // Action wrapper
    action: () => ({
        className: classNames('contextmenu-action')
    })
};

